const fmt=n=>(n<0?'−':'+')+Math.abs(n).toFixed(3);
const pFmt=n=>n<.001?'<.001':n.toFixed(3);
function renderSignificance(){
 const body=significanceResults.filter(r=>r.stage.startsWith('post')).map(r=>`<tr><th scope="row">${esc(r.label)}</th><td>${fmt(r.estimate)}</td><td>${fmt(r.low)} to ${fmt(r.high)}</td><td>${pFmt(r.p)}</td><td>${r.n.toLocaleString()}</td></tr>`).join('');
 return `<section class="significance-panel" aria-label="Direction 02 significance results">
 <div class="result-verdict"><span class="eyebrow">Answer from the existing numbers</span><h3>Positive estimate. Inconclusive evidence of a difference.</h3><p>The estimated learning benefit rises with the teacher’s baseline score. The main interaction does <strong>not pass the two-sided 5% significance threshold</strong>, and reasonable geographic controls weaken the evidence.</p></div>
 <div class="result-metrics"><div><span class="label">Additional learning benefit</span><strong>+0.132 SD</strong><p>Per one-SD higher teacher score</p></div><div><span class="label">95% confidence interval</span><strong>−0.009 to +0.273</strong><p>Includes zero and meaningful positive effects</p></div><div><span class="label">Main / bootstrap p-values</span><strong>0.067 / 0.070</strong><p>School-clustered inference in both checks</p></div></div>
 <p class="status-note">Post-test total learning · 1,625 observation rows · 101 schools · 1,610 distinct school–child ID keys. Uses observed baseline and follow-up test totals, with the original item-scoring and test-modality rules.</p>
 <p class="contrast-note"><strong>A correction for your “existing numbers only” rule:</strong> the original code retains 21 records with no baseline or post-test totals and later fills those totals with zero. The main result here excludes all 21. The source-compatible result (+0.129, p=.073; bootstrap p=.086) is retained separately for replication transparency.</p><div class="result-section"><h3>Does the answer survive reasonable analysis choices?</h3><p>Every row tests the same teacher-score interaction. All post-test models retain the same sample except the explicitly labeled repeated-ID check. None reaches p &lt; .05.</p><div class="table-scroll" tabindex="0" role="region" aria-label="All post-test specifications"><table class="results-table"><thead><tr><th scope="col">Model</th><th scope="col">Estimate</th><th scope="col">95% interval</th><th scope="col">p-value</th><th scope="col">Rows</th></tr></thead><tbody>${body}</tbody></table></div><p class="status-note">Units: SD of total learning per one-SD higher baseline teacher score. Equal-school weighting changes the target average. Geography means geographic block fixed effects, not verified randomization strata. Intervals use school-clustered standard errors and a t distribution.</p></div>
 <div class="result-section"><h3>What does that mean for lower- and higher-score schools?</h3><p>These are predicted program effects from one continuous-score model, evaluated at the school-score 25th and 75th percentiles. They are not newly selected subgroups.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Fixed teacher score contrasts"><table class="results-table"><thead><tr><th scope="col">Teacher score</th><th scope="col">Program effect</th><th scope="col">95% interval</th><th scope="col">p-value</th></tr></thead><tbody><tr><th scope="row">Lower: 25th percentile (27 points)</th><td>+0.017 SD</td><td>−0.194 to +0.228</td><td>.870</td></tr><tr><th scope="row">Higher: 75th percentile (41.75 points)</th><td>+0.204 SD</td><td>+0.007 to +0.401</td><td>.043</td></tr><tr class="key-contrast"><th scope="row">Higher minus lower: the direct comparison</th><td>+0.186 SD</td><td>−0.013 to +0.386</td><td>.067</td></tr></tbody></table></div><p class="contrast-note"><strong>The direct comparison is the new research claim.</strong> A significant effect at the higher score and an insignificant effect at the lower score do not establish that those effects differ. The high-score result is exploratory and has no multiplicity adjustment.</p></div>
 <div class="result-section"><h3>Further checks</h3><ul><li><strong>School-level bootstrap:</strong> 9,999 null-imposed wild-bootstrap draws on the 1,625 observed-test records give p=.0698 (simulation standard error .0025). Resampling measures uncertainty; it adds no people or observations.</li><li><strong>Midline, secondary source-compatible diagnostic:</strong> interaction +0.051 SD, 95% CI −0.068 to +0.171; p=.395.</li><li><strong>Influential schools, source-compatible diagnostic:</strong> omitting each school in turn gives estimates from +0.107 to +0.164. The p-values range from .015 to .126; 6 of 103 exclusions reach .05. The positive direction is stable, but significance can change. No school is selectively removed.</li><li><strong>Repeated IDs:</strong> 15 school–child keys occur twice. Excluding all 30 affected rows from the observed-test sample leaves 1,595 records and gives +0.130, p=.067. The IDs alone cannot resolve repeat observations versus identifier collisions.</li></ul><div id="attrition-result"><p class="attrition-note"><strong>Missing outcomes:</strong> 1,625 of 2,104 eligible baseline records have an observed follow-up test (77.2%); 479 are missing. Reweighting the observed tests using baseline predictors gives an interaction of +0.135 SD. A 999-draw whole-school bootstrap, refitting the weights each time, gives a 95% interval of −0.003 to +0.279. It still includes zero. This sensitivity assumes missingness is explained by the included baseline measures; it cannot verify that assumption or recover missing teacher scores.</p></div></div>
 <details class="analysis-details"><summary>Design, replication and interpretation limits</summary><div><p>The model includes treatment assignment, standardized baseline teacher score, their interaction, and the original child baseline verbal score, written score and writing-status controls. Teacher-score standardization uses the audited 107-school reference; the observed-test post model includes 101 schools. The original source-compatible sample includes 103.</p><p>All 16 Table 9 A/B checks match the <strong>released replication-package outputs</strong> for coefficients, clustered standard errors and observation counts at reported precision. Small R-squared discrepancies remain (maximum .005). The printed article lists 1,760 observations for controlled post-test Panel B; its released output and reconstructed code sample use 1,624. The Panel A reference count of 1,760 and the source-compatible extension’s 1,646-row count are unaffected. The observed-test extension then excludes the 21 zero-filled records, yielding 1,625.</p><p>The program bundles cameras and attendance-linked pay. Teacher score is a baseline characteristic, not randomized teacher ability. This interaction cannot establish a causal effect of teacher skill or prove an attendance-to-learning mechanism. Test availability and the original sample rules also limit interpretation.</p><p>The exact learning interaction was not found in the article, official appendix, erratum or targeted replication-code audit. That is a bounded originality check, not a claim about every later paper. Prior exploratory exposure is disclosed; the follow-up checks were fixed before this round, not preregistered before seeing any data. The observed-test restriction was added when the missingness audit revealed the 21 zero-filled records; that amendment is documented. Report all results, including nonsignificant ones.</p><p><a href="https://www.stata.com/manuals/rwildbootstrap.pdf" target="_blank" rel="noopener">Wild-cluster bootstrap method reference ↗</a></p></div></details>
 <div class="result-downloads"><a href="direction02-all-models.csv" download>Download every model coefficient (CSV)</a><a href="direction02-replication-sample-models.csv" download>Replication-sample models (CSV)</a><a href="direction02-results.md" download>Download results and limitations</a></div>
 </section>`;
}


function renderRetention(){
 const names={drop:'NFE departure / sustained absence',gov:'Recorded government-school transfer',drop2:'Departure without a recorded transfer marker'};
 const main=retentionResults.filter(r=>r.model==='primary_consensus_no_fe');
 return `<section class="significance-panel" aria-label="Revised scope significance results"><div class="result-verdict"><span class="eyebrow">The stronger scope</span><h3>A significant difference in who leaves the original school.</h3><p>The program increases the study’s NFE-departure classification more among baseline writers than nonwriters. The <strong>direct difference</strong> passes the two-sided 5% test and the fixed three-outcome adjustment.</p></div>
 <div class="result-metrics"><div><span class="label">Writer minus nonwriter effect</span><strong>+21.1 points</strong><p>95% CI +6.9 to +35.3 percentage points</p></div><div><span class="label">Raw / adjusted p-values</span><strong>.004 / .012</strong><p>Holm adjustment across three schooling outcomes</p></div><div><span class="label">School-level bootstrap</span><strong>p = .0072</strong><p>9,999 null-imposed draws · 111 schools</p></div></div>
 <p class="status-note">2,195 children · 397 baseline writers and 1,798 nonwriters · two conflicting IDs excluded · same original raw measurements.</p>
 <div class="result-section"><h3>What changes in the scope?</h3><p>Move from <strong>teacher score → differences in learning gains</strong> to <strong>children’s initial writing ability → differences in departure from the original school</strong>. Earlier Direction 03 asked about government-school transfer; that interaction remains nonsignificant. The revised endpoint includes all recorded NFE departures, without claiming to know each child’s later destination.</p></div>
 <div class="result-section"><h3>The group effects—and the comparison that matters</h3><div class="table-scroll" tabindex="0" role="region" aria-label="Departure by baseline writing"><table class="results-table"><thead><tr><th scope="col">Initial preparation</th><th scope="col">Control departure</th><th scope="col">Treatment departure</th><th scope="col">Program effect</th></tr></thead><tbody><tr><th scope="row">Could not take written baseline test</th><td>33.8%</td><td>38.8%</td><td>+5.0 points</td></tr><tr><th scope="row">Took written baseline test</th><td>44.3%</td><td>70.4%</td><td>+26.1 points</td></tr><tr class="key-contrast"><th scope="row">Difference between program effects</th><td colspan="2">95% CI +6.9 to +35.3 points</td><td><strong>+21.1 points</strong></td></tr></tbody></table></div><p class="status-note">Nonwriter effect CI −2.4 to +12.4 points; writer effect CI +10.0 to +42.3. The headline is the directly tested +21.1-point difference, not a comparison of two separate significance labels.</p></div>
 <div class="result-section"><h3>All three original outcome definitions examined</h3><div class="table-scroll" tabindex="0" role="region" aria-label="Fixed schooling outcome family"><table class="results-table"><thead><tr><th scope="col">Outcome</th><th scope="col">Difference in effects</th><th scope="col">Raw p</th><th scope="col">Holm p</th></tr></thead><tbody>${main.map(r=>`<tr><th scope="row">${names[r.outcome]}</th><td>+${(100*r.estimate).toFixed(1)} points</td><td>${r.p.toFixed(3)}</td><td>${r.holm.toFixed(3)}</td></tr>`).join('')}</tbody></table></div><p class="contrast-note"><strong>Departure is not necessarily bad.</strong> It may include progression to formal school. The main result does not use transfer-reason coding. Harmonizing the raw numeric transfer code changes 13 destination classifications in the 2,197-child replication sample, but leaves every total-departure classification unchanged. The +16.3-point secondary contrast does use that coding, so it cannot establish an increase in dropout from education altogether.</p></div>
 <div class="result-section"><h3>Does the main departure result survive checks?</h3><div class="table-scroll" tabindex="0" role="region" aria-label="Departure sensitivity checks"><table class="results-table"><thead><tr><th scope="col">Check</th><th scope="col">Difference in effects</th><th scope="col">95% interval</th><th scope="col">p-value</th></tr></thead><tbody><tr><th scope="row">Main departure model</th><td>+21.1 points</td><td>+6.9 to +35.3</td><td>.004</td></tr><tr><th scope="row">Add geographic controls</th><td>+22.1 points</td><td>+8.2 to +36.0</td><td>.002</td></tr><tr><th scope="row">End observation at December 2005</th><td>+19.7 points</td><td>+4.8 to +34.6</td><td>.010</td></tr><tr><th scope="row">Exclude every ambiguous departure code</th><td>+26.6 points</td><td>+12.0 to +41.2</td><td>.00046</td></tr></tbody></table></div><p class="status-note">The first three rows use the same 2,195 children; the final row uses 2,082 and is an explicitly selected-sample sensitivity. The December endpoint removes the final January–February 2006 observations with lost reason codes; it does not repair December coding or eliminate the coverage issue. The date was fixed for that data issue, not by searching dates for significance. Geographic blocks are not asserted to be randomization strata.</p></div>
 <div class="result-section"><h3>The remaining observation and coding issues</h3><p>The paper classifies children as leaving when they are absent at every one of their last <strong>up to five checks at which the school was open</strong>. Treatment makes schools open more often, so the observation process differs across arms.</p><p>The original code also maps undocumented negative attendance codes to absence. An independent audit found 113 departure classifications that depend on at least one such code or code 22; excluding all 113 in a fixed sensitivity gives +26.6 points (95% CI +12.0 to +41.2), p=.00046 and school-bootstrap p=.0011, using 2,082 children. This changes the analyzed sample and does not prove that missingness is random. Treating all 113 as unknown gives an observed-sample range of +16.3 to +34.1 points; including all incomplete five-check histories gives +8.8 to +45.6. These are not confidence intervals and do not establish significance under every coding. For 145 children, fewer than five open checks are available. Treating all 145 outcomes as unknown gives a worst-case range of <strong>+11.9 to +36.4 points</strong> for the difference. That range stays positive in the observed sample, but <strong>it is not a confidence interval</strong> and does not remove sampling uncertainty or different calendar coverage.</p><p class="attrition-note"><strong>Scope the claim precisely:</strong> “The program’s effect on recorded NFE departure differs by baseline writing status.” Avoid “the program causes prepared children to abandon education.” The second statement requires destination evidence this dataset does not reliably provide.</p></div>
 <details class="analysis-details"><summary>What else was tried—and why it is not the recommendation</summary><div><p><strong>Teacher-score × total learning:</strong> p=.067; school bootstrap=.070. No robust 5% result.</p><p><strong>Mathematics-only moderation:</strong> +0.209 SD, raw p=.037, but Holm p=.110 across math, language and total, and p=.158 with geography controls. The joint math/language test has p=.090; the math-minus-language contrast has p=.054. Selecting math alone would overstate the evidence.</p><p><strong>Broader learning distribution:</strong> using 1,737 observed-test records and 107 schools, the primary 25th-percentile difference is +0.081 SD, approximate school-bootstrap p=.310. Median, upper quartile and interquartile-spread intervals also include zero. No alternative percentile was searched.</p><p><strong>Exploration disclosure:</strong> the families were fixed before their new computations, after earlier data exploration. This is not preregistered or independent confirmation. The schooling Holm adjustment covers its three outcomes; it does not erase the wider search history.</p></div></details>
 <div class="result-downloads"><a href="scope-results.md" download>Download the scope decision and full results</a><a href="scope-pathways.csv" download>All schooling specifications (CSV)</a><a href="scope-learning.csv" download>Learning-domain checks (CSV)</a><a href="scope-distribution.csv" download>Distribution checks (CSV)</a></div>
 </section>`;
}

let selected='transition';
let view='explore';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderDirection(){
 const o=options[selected];
 const a=auditEvidence[selected];
 document.getElementById('direction').innerHTML=`
 ${selected==='transition'?window.studyVisuals.render():''}<header class="direction-head" id="detailed-analysis"><div class="heading-line"><span class="eyebrow">Direction ${o.number} · ${esc(o.label)}</span><span class="badge ${selected==='learning'?'amber':''}">${esc(o.badge)}</span></div><h2 id="direction-title">${esc(o.question)}</h2><p class="lead">${esc(o.lead)}</p><div class="facts"><div class="fact"><span class="label">Effort</span><strong>${esc(o.effort)}</strong></div><div class="fact"><span class="label">Starting point</span><strong>${esc(o.readiness)}</strong></div><div class="fact"><span class="label">Contribution</span><strong>${esc(o.contribution)}</strong></div></div></header>
 ${selected==='learning'?renderSignificance():selected==='transition'?renderRetention():''}<div class="content-grid"><div class="content-main">${a&&selected!=='learning'&&selected!=='transition'?`<section class="audit-panel" aria-label="Verification results"><h3>${esc(a.headline)}</h3><p>${esc(a.replication)}</p><p class="audit-result">${esc(a.result)}</p><p>${esc(a.meaning)}</p><p class="status-note">${esc(a.interval)}</p><p><strong>What that supports:</strong> ${esc(a.interpretation)}</p><p>${esc(a.sensitivity)}</p><p class="status-note">${esc(a.caution)}</p>${a.secondary?`<details><summary>Exploratory secondary dropout signal</summary><p>${esc(a.secondary)}</p></details>`:''}</section>`:''}<section class="block"><h3>Why this question is worth asking</h3><p>${esc(o.why)}</p></section><section class="block distinction"><strong>Already in the original paper</strong><p>${esc(o.original)}</p><strong>What your work would add</strong><p>${esc(o.addition)}</p></section><section class="block"><h3>The analysis approach</h3><ol class="steps">${o.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section><section class="block caution"><h3>The main interpretation risk</h3><p>${esc(o.cautions)}</p></section><section class="block go-gate"><h3>Before you commit</h3><p>${esc(o.gate)}</p></section></div><aside class="content-aside" aria-label="Data and deliverables"><section class="block"><h3>The data are already here</h3>${o.data.map(d=>`<div class="data-item"><strong>${esc(d[0])}</strong><span>${esc(d[1])}</span><span class="path">${esc(d[2])}</span></div>`).join('')}<p style="font-size:12px;color:var(--muted);margin-top:12px">Paths refer to the existing local replication package. Data files are not uploaded to this site.</p></section><section class="block"><h3>A focused output</h3><p>${esc(o.deliverable)}</p>${o.evidence?`<div class="evidence-box"><h3>${esc(o.evidence.label)}</h3><div class="stat">${esc(o.evidence.stat)}</div><p>${esc(o.evidence.text)}</p></div>`:''}</section></aside></div><footer class="source-row">Evidence: ${esc(o.source)} <a href="https://www.aeaweb.org/articles?id=10.1257/aer.102.4.1241" target="_blank" rel="noopener">Study ↗</a></footer>`;
 document.querySelectorAll('.option-nav [data-option]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.option===selected)));
}
function setView(next){
 if(!['explore','compare'].includes(next))throw new Error('Unknown view');
 view=next;
 document.getElementById('explore-view').hidden=next!=='explore';
 document.getElementById('compare-view').hidden=next!=='compare';
 document.getElementById('explore-button').setAttribute('aria-pressed',String(next==='explore'));
 document.getElementById('compare-button').setAttribute('aria-pressed',String(next==='compare'));
}
function selectOption(id){
 if(!Object.hasOwn(options,id))throw new Error('Unknown research direction');
 selected=id;renderDirection();setView('explore');
}
document.getElementById('comparison-rows').innerHTML=['transition','learning','gradient','robustness'].map(id=>[id,options[id]]).map(([id,o])=>`<tr><td><button data-option="${id}">${o.number} · ${esc(o.title)}</button><p>${esc(o.effort)} effort</p></td><td>${esc(o.compareAdd)}</td><td>${esc(o.compareWork)}</td><td>${esc(o.compareRisk)}</td></tr>`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('[data-option]');if(b){selectOption(b.dataset.option);if(window.scrollY>430)document.getElementById('direction').scrollIntoView({block:'start'});}});
document.getElementById('explore-button').addEventListener('click',()=>setView('explore'));
document.getElementById('compare-button').addEventListener('click',()=>setView('compare'));
renderDirection();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tools=[
 {name:'read_research_visual',description:'Read the currently selected visual explanation and the verified aggregate chart data. No analysis is rerun.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({direction:selected,visual:window.studyVisuals.getState(),data:window.researchVisualData,caveat:'Recorded NFE departure is an attendance-based classification, not proven educational dropout. Confidence intervals and exploratory p-values remain subject to measurement limits.'})},
 {name:'show_research_visual',description:'Show one visual explanation of the departure analysis. This only changes the page view.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['rates','difference','uncertainty','checks','quality']},chart:{type:'string',enum:['bars','pies']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!['rates','difference','uncertainty','checks','quality'].includes(input.mode)||Object.keys(input).some(k=>!['mode','chart'].includes(k))||(input.chart&&!['bars','pies'].includes(input.chart)))throw new Error('Provide a valid visual mode and optional bars or pies chart');if(selected!=='transition')selectOption('transition');window.studyVisuals.show(input.mode,input.chart);return window.studyVisuals.getState();}},
 {name:'read_research_directions',description:'Read the two surviving research candidates and two rejected directions, including feasibility and selected direction.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({selected,view,options:Object.entries(options).map(([id,o])=>({id,question:o.question,effort:o.effort,readiness:o.readiness,contribution:o.contribution,caution:o.cautions,results:id==='learning'?significanceResults:id==='transition'?retentionResults:undefined}))})},
 {name:'show_research_direction',description:'Display one research direction in the page. This navigates the comparison; it does not commit to or run the study.',inputSchema:{type:'object',properties:{id:{type:'string',enum:Object.keys(options)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.id!=='string'||Object.keys(input).some(k=>k!=='id'))throw new Error('Provide one valid direction id');selectOption(input.id);return {selected,view,question:options[selected].question};}}
 ];
 for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
